STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_CURSE_MONKEY = "이 음식을 먹으면 달 부두 섬의 저주를 풀 수 있습니다."
STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_CRAFTING = "이 음식을 먹으면 제작대 없이도 새로운 아이템을 프로토타입하고 제작할 수 있습니다.\n\n아이템을 제작할 때마다 소량의 정신력이 소모됩니다."
STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_BEEFRIENDLY = "이 음식을 먹으면 일정 시간 동안 벌들이 당신에게 적대적이지 않고 온순해집니다."
STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_HOFBIRTHDAY_SLICE1 = "일정 시간 동안 최대 허기가 15% 증가합니다.\n\n음식 더미(Heap of Foods)의 5주년을 기념합니다!"
STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_HOFBIRTHDAY_SLICE2 = "일정 시간 동안 최대 체력이 15% 증가합니다.\n\n음식 더미(Heap of Foods)의 5주년을 기념합니다!"
STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_HOFBIRTHDAY_SLICE3 = "일정 시간 동안 최대 정신력이 15% 증가합니다.\n\n음식 더미(Heap of Foods)의 5주년을 기념합니다!"
STRINGS.SCRAPBOOK.SPECIALINFO.FOODEFFECTS_BERSERKER = "일정 시간 동안 공격력이 증가하고 피해 저항력이 감소합니다."
